    if (!input.materialState || input.materialState === 'unknown') return { status: 'state-missing', curve, reason: 'Lieferzustand des Drahts fehlt' };
    if (input.materialState !== curve.state) return { status: 'state-mismatch', curve, reason: 'Lieferzustand passt nicht zur ausgewählten Fließkurve' };
    if (input.temperature !== undefined && input.temperature !== curve.temperature) return { status: 'temperature-mismatch', curve, reason: 'Temperatur passt nicht zum Quellenbereich der Fließkurve' };
