  const pos = x => typeof x === 'number' && isFinite(x) && x > 0;
  // Qualitative Metadaten zur tatsächlich berechneten Operation; keine zusätzliche Stufe.
  const op = (name, location) => ({ name, location });
  const r1 = x => Math.round(x * 10) / 10;
