          out.stufen.push({ v: 'Reduzieren ' + z(d0) + ' → ' + z(sD) + ' (' + Math.round(eps * 100) + ' %), mit Vorstauchen', F: fpKraft(m, A0, 0, phiSchaft, true, 0, d0), A: A0, bohr: d0, r: 'R-F2', mit: true, operations: [op('Reduzieren', 'Schaft / Körper')] });
